const { useEffect, useRef } = React;

// 同样 300×150 的 CSS 尺寸：左边画布像素与 CSS 尺寸相同，右边按 DPR 放大并 scale
const drawSample = (ctx, color) => {
  ctx.strokeStyle = color("accent");
  ctx.lineWidth = 2;
  ctx.strokeRect(20, 20, 110, 110);
  ctx.beginPath();
  ctx.arc(215, 75, 55, 0, Math.PI * 2);
  ctx.stroke();
  ctx.font = `600 18px ${color("font")}`;
  ctx.fillStyle = color("ink-1");
  ctx.fillText("Canvas", 35, 82);
};

const useFixedCanvas = (scaled, color) => {
  const ref = useRef(null);
  useEffect(() => {
    const canvas = ref.current;
    const ctx = canvas?.getContext("2d");
    if (!canvas || !ctx) return;
    const dpr = scaled ? window.devicePixelRatio || 1 : 1;
    canvas.width = 300 * dpr;
    canvas.height = 150 * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, 300, 150);
    drawSample(ctx, color);
  }, [color]);
  return ref;
};

const Component = () => {
  const { color } = useTokens();
  const blurryRef = useFixedCanvas(false, color);
  const sharpRef = useFixedCanvas(true, color);
  const dpr = typeof window === "undefined" ? 1 : window.devicePixelRatio || 1;

  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-wrap gap-4">
        {[
          [blurryRef, "画布尺寸 = CSS 尺寸", "red"],
          [sharpRef, "画布尺寸 = CSS 尺寸 × dpr，并 scale(dpr)", "green"],
        ].map(([ref, label, tone]) => (
          <figure key={label} className="m-0 flex flex-col gap-2">
            <canvas ref={ref} className="block rounded-tau-md border border-line-1" style={{ width: 300, height: 150 }} />
            <figcaption className="flex items-center gap-2">
              <ui.Tag color={tone}>{tone === "red" ? "模糊" : "清晰"}</ui.Tag>
              <span className="text-tau-meta text-ink-3">{label}</span>
            </figcaption>
          </figure>
        ))}
      </div>
      <code className="self-start rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">
        window.devicePixelRatio = {dpr}
      </code>
      {dpr === 1 && <span className="text-tau-meta text-ink-3">当前屏幕 dpr 为 1，两者看起来一样；在高分屏上差异明显</span>}
    </div>
  );
};
